import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"推广员体系","description":"灵萌推广员配置：区域推广开关、邀请奖励、全员推广模式、推广员审核与邀请记录。","frontmatter":{"title":"推广员体系","description":"灵萌推广员配置：区域推广开关、邀请奖励、全员推广模式、推广员审核与邀请记录。"},"headers":[],"relativePath":"features/promotion.md","filePath":"features/promotion.md","lastUpdated":1785020677000}'),i={name:"features/promotion.md"};function e(n,t,s,h,d,p){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="推广员体系" tabindex="-1">推广员体系 <a class="header-anchor" href="#推广员体系" aria-label="Permalink to &quot;推广员体系&quot;">​</a></h1><p>路径：<strong>平台推广 → 推广员</strong></p><p>通过邀请关系拉新，并按规则发放余额/积分奖励。规则按<strong>区域</strong>配置。</p><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>推广相关模块已开通（<strong>系统设置 → 我的模块</strong>）</li><li>已创建目标区域（<strong>区域管理 → 区域列表</strong>）</li><li>若奖励发到余额，确认 <a href="/features/payment">支付与资金</a> / 账本可用</li></ul><hr><h2 id="一、推广配置-必做" tabindex="-1">一、推广配置（必做） <a class="header-anchor" href="#一、推广配置-必做" aria-label="Permalink to &quot;一、推广配置（必做）&quot;">​</a></h2><p>路径：<strong>平台推广 → 推广员 → 推广配置</strong></p><ol><li>选择区域（或平台默认）</li><li>打开 <strong>启用推广</strong>（总开关；关闭后注册/登录不会完成绑定发奖）</li><li>按运营模式选择： <ul><li><strong>仅推广员</strong>：需先通过推广员审核，再邀请</li><li><strong>全员推广模式</strong>：普通用户也可邀请（页面会显示「全员推广」chip）</li></ul></li><li>填写奖励： <ul><li>推广员邀请奖励：邀请人 / 被邀请人 · 余额或积分</li><li>全员推广奖励（若开启全员模式）</li></ul></li><li><strong>注册后绑定天数</strong>：超过天数未绑定则失效；填 <code>0</code> 表示不限制</li><li>资金策略（如有）： <ul><li><strong>使用负责人账户发奖</strong></li><li><strong>负责人不足时跳过发奖</strong></li></ul></li><li>配置推广默认标题、封面（分享用）</li><li>点 <strong>保存配置</strong></li></ol><p>页面状态 chip 会显示：推广已启用/关闭、全员推广/仅推广员、是否继承平台默认。</p><div class="tip custom-block"><p class="custom-block-title">区域继承</p><p>区域编号 0 为平台默认。未单独配置的区域继承平台行。需要某校区单独奖励时，为该区域新建/编辑一行。</p></div><hr><h2 id="二、推广员审核" tabindex="-1">二、推广员审核 <a class="header-anchor" href="#二、推广员审核" aria-label="Permalink to &quot;二、推广员审核&quot;">​</a></h2><p>路径：<strong>平台推广 → 推广员 → 推广员审核</strong></p><ol><li>用户在客户端提交推广员申请（入口以 UI 配置为准）</li><li>后台审核通过 / 拒绝</li><li>通过后该用户可按「仅推广员」模式邀请他人</li></ol><hr><h2 id="三、邀请记录" tabindex="-1">三、邀请记录 <a class="header-anchor" href="#三、邀请记录" aria-label="Permalink to &quot;三、邀请记录&quot;">​</a></h2><p>路径：<strong>平台推广 → 推广员 → 邀请记录</strong></p><p>查看邀请关系、是否发奖成功，便于对账与客诉。</p><p>奖励入账可在 <strong>财务管理 → 余额流水 / 积分流水</strong> 核对。</p><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>测试区域 <strong>启用推广</strong> 并设小额奖励</li><li>（仅推广员模式）审核通过一个测试推广员</li><li>用邀请链接注册新用户，在绑定天数内完成注册/登录</li><li><strong>邀请记录</strong> 有关系；邀请人/被邀请人流水有奖励（按配置）</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>邀请无奖励</td><td>推广是否启用；是否超过绑定天数；负责人账户是否不足且开启了跳过</td></tr><tr><td>用户申请不了推广员</td><td>UI 是否有入口；区域是否仅全员模式导致无需申请</td></tr><tr><td>侧栏无推广</td><td>模块未开通或账号无权限</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/coupon">优惠券与营销</a></li><li><a href="/features/payment">支付与提现</a></li><li><a href="/features/finance">财务流水与提现</a></li></ul>',30)])])}const g=a(i,[["render",e]]);export{u as __pageData,g as default};
